#!/usr/bin/env python3
"""Share peer reviewers automatically. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/services/reviewer_share.py': ''}
MOD = {'backend/app/core/scheduler.py': [('        enh.run_reminders(db)\n        try:\n            from app.services import balance, distribute\n            distribute.run_all(db)\n            balance.run_all(db)\n        except Exception as e:', '        enh.run_reminders(db)\n        try:\n            from app.services import balance, distribute, reviewer_share\n            distribute.run_all(db)\n            reviewer_share.run_all(db)\n            balance.run_all(db)\n        except Exception as e:')], 'backend/app/api/v1/routes/dispatch.py': [('from app.models.all_models import Project, Source, SourceStatus, User\nfrom app.services import distribute as dist\nfrom app.services import holds\nfrom app.services import quality as q', 'from app.models.all_models import Project, Source, SourceStatus, User\nfrom app.services import distribute as dist\nfrom app.services import reviewer_share as rev\nfrom app.services import holds\nfrom app.services import quality as q'), ('    items.sort(key=lambda x: x["since"])\n    return {"project_id": p.id, "project": p.name, "batches": sorted(batches.values(), key=lambda g: (g["key"] == "other", g["date"]), reverse=True),\n            "held": items, "held_count": len(items), "unassigned": dist.waiting_summary(db, p.id), "auto_share": dist.auto_on(db, p.id)}\n\n', '    items.sort(key=lambda x: x["since"])\n    return {"project_id": p.id, "project": p.name, "batches": sorted(batches.values(), key=lambda g: (g["key"] == "other", g["date"]), reverse=True),\n            "held": items, "held_count": len(items), "unassigned": dist.waiting_summary(db, p.id), "auto_share": dist.auto_on(db, p.id), "reviewers": rev.summary(db, p.id)}\n\n'), ('    return _view(db, user, p)\n', '    return _view(db, user, p)\n\n\nclass ReviewersBody(BaseModel):\n    scope: str = "ready"                    # ready = extraction finished; all_open = every open source that has an extractor\n    batch_key: str | None = None\n\n\n@router.post("/{project_id}/reviewers")\ndef share_reviewers(project_id: str, body: ReviewersBody, db: Session = Depends(get_db), user: User = Depends(get_current_user)):\n    _need_lead(user)\n    p = _project(db, user, project_id)\n    r = rev.run_project(db, p.id, scope="all_open" if body.scope == "all_open" else "ready", batch_key=body.batch_key, by_user_id=user.id)\n    per: dict = {}\n    for a in r["assigned"]:\n        for n in a["reviewers"]:\n            per[n] = per.get(n, 0) + 1\n    return {"assigned": len(r["assigned"]), "left": r["left"], "reason": r["reason"], "per_person": per, "view": _view(db, user, p)}\n\n\nclass ReviewerSettings(BaseModel):\n    auto: bool | None = None\n    count: int | None = None\n\n\n@router.put("/{project_id}/reviewers-auto")\ndef reviewers_auto(project_id: str, body: ReviewerSettings, db: Session = Depends(get_db), user: User = Depends(get_current_user)):\n    if not (_roles(user) & {"org_admin", "project_admin"}):\n        raise HTTPException(status_code=403, detail="Only admins can change this.")\n    p = _project(db, user, project_id)\n    rev.set_settings(db, p.id, auto=body.auto, count=body.count)\n    db.commit()\n    return _view(db, user, p)\n')], 'frontend/src/api/dispatch.ts': [('  share: (projectId: string, body: { batch_key?: string; source_ids?: string[] }) =>\n    api.post(`/dispatch/${projectId}/share`, body).then(r => r.data as { assigned: number; left: number; reason: string | null; per_person: Record<string, number>; view: any }),\n  auto: (projectId: string, auto_share: boolean) => api.put(`/dispatch/${projectId}/auto`, { auto_share }).then(r => r.data),\n}', "  share: (projectId: string, body: { batch_key?: string; source_ids?: string[] }) =>\n    api.post(`/dispatch/${projectId}/share`, body).then(r => r.data as { assigned: number; left: number; reason: string | null; per_person: Record<string, number>; view: any }),\n  reviewers: (projectId: string, body: { scope?: 'ready' | 'all_open'; batch_key?: string }) =>\n    api.post(`/dispatch/${projectId}/reviewers`, body).then(r => r.data as { assigned: number; left: number; reason: string | null; per_person: Record<string, number>; view: any }),\n  reviewerSettings: (projectId: string, body: { auto?: boolean; count?: number }) => api.put(`/dispatch/${projectId}/reviewers-auto`, body).then(r => r.data),\n  auto: (projectId: string, auto_share: boolean) => api.put(`/dispatch/${projectId}/auto`, { auto_share }).then(r => r.data),\n}")], 'frontend/src/components/enh/DispatchPanel.tsx': [("  const share = (key?: string) => act(() => dispatchApi.share(projectId, key ? { batch_key: key } : {}), r =>\n    r.assigned ? `${r.assigned} shared: ${Object.entries(r.per_person).map(([n, c]) => `${n} ${c}`).join(', ')}` : (r.reason || 'Nothing to share'))\n  const hold = (key: string, on: boolean) => act(() => dispatchApi.hold(projectId, { hold: on, batch_key: key }), r => r.changed ? `${r.changed} ${on ? 'put on hold' : 'released'}` : (on ? 'Nothing to hold in this pull' : 'Nothing was on hold'))\n", "  const share = (key?: string) => act(() => dispatchApi.share(projectId, key ? { batch_key: key } : {}), r =>\n    r.assigned ? `${r.assigned} shared: ${Object.entries(r.per_person).map(([n, c]) => `${n} ${c}`).join(', ')}` : (r.reason || 'Nothing to share'))\n  const shareRev = (scope: 'ready' | 'all_open') => act(() => dispatchApi.reviewers(projectId, { scope }), r =>\n    r.assigned ? `${r.assigned} ${r.assigned === 1 ? 'source' : 'sources'} given reviewers: ${Object.entries(r.per_person).map(([n, c]) => `${n} ${c}`).join(', ')}` : (r.reason || 'Nothing needs a reviewer'))\n  const hold = (key: string, on: boolean) => act(() => dispatchApi.hold(projectId, { hold: on, batch_key: key }), r => r.changed ? `${r.changed} ${on ? 'put on hold' : 'released'}` : (on ? 'Nothing to hold in this pull' : 'Nothing was on hold'))\n"), ('                  <span className="text-gray-500">Checked every 30 minutes. Nothing already owned or started is touched.</span></div>\n              )}\n              {d.held.length > 0 && (\n                <Panel title="On hold" subtitle="The clock is stopped for these">', '                  <span className="text-gray-500">Checked every 30 minutes. Nothing already owned or started is touched.</span></div>\n              )}\n              <Panel title="Peer reviewers" subtitle="Each source without a reviewer gets the people with the fewest reviews waiting. Never its own extractor, and never someone set aside as away in Work balance.">\n                <div className="flex items-center gap-3 flex-wrap">\n                  <Button variant="secondary" size="sm" disabled={busy || !d.reviewers.waiting} onClick={() => shareRev(\'ready\')}>Give reviewers to {d.reviewers.waiting} finished {d.reviewers.waiting === 1 ? \'source\' : \'sources\'}</Button>\n                  {d.reviewers.waiting_all > d.reviewers.waiting && <Button variant="secondary" size="sm" disabled={busy} onClick={() => shareRev(\'all_open\')}>Include {d.reviewers.waiting_all - d.reviewers.waiting} still being extracted</Button>}\n                  {isAdmin && (<>\n                    <label className="flex items-center gap-2 text-sm">Reviewers per source\n                      <select className="rounded-lg border px-2 py-1 text-sm bg-transparent" value={d.reviewers.count} disabled={busy} onChange={e => act(() => dispatchApi.reviewerSettings(projectId, { count: Number(e.target.value) }))}>{[1, 2, 3].map(n => <option key={n} value={n}>{n}</option>)}</select></label>\n                    <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={d.reviewers.auto} disabled={busy} onChange={e => act(() => dispatchApi.reviewerSettings(projectId, { auto: e.target.checked }))} /> Give reviewers automatically when extraction finishes</label>\n                  </>)}\n                </div>\n                {d.reviewers.people.length > 0 && <p className="text-xs text-gray-500 mt-3 mb-0">Reviews waiting now: {d.reviewers.people.map((p: any) => `${p.name} ${p.pending}`).join(\' · \')}</p>}\n              </Panel>\n              {d.held.length > 0 && (\n                <Panel title="On hold" subtitle="The clock is stopped for these">')]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
